import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"常见错误与修复","description":"","frontmatter":{},"headers":[],"relativePath":"zh/troubleshooting/common-errors.md","filePath":"zh/troubleshooting/common-errors.md"}'),a={name:"zh/troubleshooting/common-errors.md"};function c(h,t,i,s,n,l){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="常见错误与修复" tabindex="-1">常见错误与修复 <a class="header-anchor" href="#常见错误与修复" aria-label="Permalink to &quot;常见错误与修复&quot;">​</a></h1><h2 id="构建" tabindex="-1">构建 <a class="header-anchor" href="#构建" aria-label="Permalink to &quot;构建&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>原因</th><th>修复方法</th></tr></thead><tbody><tr><td><code>grub-mkimage: cannot open ... unicode.pf2</code></td><td>字体文件位于 <code>grub-common</code> 中</td><td>安装它 / 将 OC_TOOLS 指向包含 <code>usr/share/grub/unicode.pf2</code> 的目录树</td></tr><tr><td><code>src-zip: not a git checkout</code></td><td>没有 git 元数据</td><td>从克隆版本构建或使用 <code>make dist</code></td></tr><tr><td><code>error: operand size mismatch for &#39;setc&#39;</code></td><td>新版 GAS 上的前缀树</td><td>更新到 fc4e5a5 提交之后（u8 标志）</td></tr><tr><td>新版 GCC 上的 packed-member 警告</td><td>前缀树</td><td>更新到 fc4e5a5 提交之后（packed 标记类型）</td></tr><tr><td><code>embed_grub: missing /usr/usr/lib/grub...</code></td><td>前缀脚本</td><td>更新到 fc4e5a5 提交之后（双布局探测）</td></tr></tbody></table><h2 id="启动" tabindex="-1">启动 <a class="header-anchor" href="#启动" aria-label="Permalink to &quot;启动&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>含义</th><th>下一步</th></tr></thead><tbody><tr><td>没有 <code>multiboot2 handshake OK</code></td><td>GRUB 没有传递有效的 mbi</td><td>检查 ISO 是否启动了正确的条目；捕获串口输出</td></tr><tr><td>启动停在非 OK 行</td><td>该子系统失败</td><td>实现它的文件 - 阅读其初始化错误路径</td></tr><tr><td>三重故障/复位循环</td><td>在转储路径工作前出现早期异常</td><td><code>-d int,cpu_reset -D qemu.log</code> + 通过 <code>-s -S</code> 使用 gdb</td></tr><tr><td>GRUB 菜单启动了错误的槽位</td><td>过期的 A/B 标志</td><td>从菜单强制选择另一个槽位，然后执行 <code>update rollback</code></td></tr></tbody></table><h2 id="运行时" tabindex="-1">运行时 <a class="header-anchor" href="#运行时" aria-label="Permalink to &quot;运行时&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>含义</th><th>下一步</th></tr></thead><tbody><tr><td><code>mount</code> 拒绝有效的 FAT32 卷</td><td>BPB 检查失败</td><td><code>fatstat &lt;dev&gt;</code> 显示解析的 BPB；设备错误？</td></tr><tr><td>网卡静默</td><td>驱动未绑定</td><td><code>lspci</code> + 家族命令（<code>e1000</code>...）</td></tr><tr><td>TCP 连接后停滞</td><td>校验和/重构回归</td><td><code>tcpstats</code>, <code>tcptest</code></td></tr><tr><td><code>usda</code> 缺失</td><td>USB MSC 未绑定</td><td><code>usb</code>, <code>usb_storage_test</code></td></tr><tr><td>fsck 报告在干净卸载后仍为脏</td><td>FSINFO/FAT 镜像回归</td><td>报告此问题 - 这属于一类错误</td></tr></tbody></table><h2 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to &quot;测试&quot;">​</a></h2><ul><li>SSH E2E 需要预置的 /etc 卷（<code>host_keygen_etc</code>）。</li><li>HTTPS E2E 需要可访问的参考服务器。</li><li>回归测试套件需要 pexpect；SSH 套件需要 paramiko。</li></ul>',9)])])}const m=d(a,[["render",c]]);export{u as __pageData,m as default};
